import {DURATION,STYLES,createInitialState,formatTime,activeCard,action,clamp} from './model.js';

let state=createInitialState();
const root=document.querySelector('#app');
const videoSource='./assets/aroll-preview.mp4';
const icon={spark:'✳',play:'▶',pause:'Ⅱ',back:'↶',forward:'↷',search:'⌕',more:'···'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const styleBy=id=>STYLES.find(x=>x.id===id);
const statusText=c=>c.status==='missing'?'缺少素材':c.status==='accepted'?'已采纳':c.status==='kept'?'保留口播':c.decision==='keep'?'建议不加':'待判断';
const displayCards=()=>state.cards.filter(c=>state.filter==='all'||(state.filter==='pending'&&c.status==='pending')||(state.filter==='missing'&&c.status==='missing')||(state.filter==='done'&&['accepted','kept'].includes(c.status)));
function cardMarkup(c){
  const chosen=state.checked.includes(c.id),sel=state.selected===c.id;
  return `<article class="decision ${sel?'selected':''} ${c.status}" data-select="${c.id}" tabindex="0" aria-label="跳到 ${formatTime(c.start)} ${esc(c.text)}">
    <div class="decision-top"><label class="check-wrap" title="加入批量选择"><input type="checkbox" data-check="${c.id}" ${chosen?'checked':''}><span></span></label><span class="timecode">${formatTime(c.start)} — ${formatTime(c.end)}</span><span class="status ${c.status}">${statusText(c)}</span></div>
    <p class="decision-quote">${esc(c.text)}</p><div class="decision-foot"><span class="tiny-mark ${c.decision}"></span><span>${c.decision==='broll'?(styleBy(c.style)?.name||'待选样式'):c.decision==='missing'?'待补：夜间工作画面':'原镜头保留'}</span><span class="chevron">↗</span></div>
  </article>`;
}
function decisionPanel(){let cards=displayCards(),selected=state.checked.length;
  return `<aside class="queue panel"><div class="queue-heading"><div class="eyebrow">01 / AGENT REVIEW</div><h2>逐段判断<span class="count">06</span></h2><p>先决定哪里该出现画面，再处理每段的内容和节奏。</p></div>
    <div class="filter-row">${[['all','全部'],['pending','待判断'],['missing','缺口'],['done','已处理']].map(([key,label])=>`<button data-filter="${key}" class="filter ${state.filter===key?'active':''}">${label}</button>`).join('')}</div>
    <div class="queue-select"><label><input type="checkbox" data-check-all ${cards.length&&cards.every(c=>state.checked.includes(c.id))?'checked':''}> 选择当前列表</label><span>${cards.length} 个判断</span></div>
    <div class="decision-list">${cards.map(cardMarkup).join('')||'<div class="empty">这个筛选里没有片段</div>'}</div>
    <div class="batch-area ${selected?'has-selection':''}"><div class="batch-head"><span>${selected?`已选择 <b>${selected}</b> 段`:'批量审看'}</span><button data-action="clear-check" ${selected?'':'disabled'}>清空</button></div><div class="batch-buttons"><button data-action="bulk-keep" ${selected?'':'disabled'}>保留原镜头</button><button class="strong" data-action="bulk-accept" ${selected?'':'disabled'}>采纳有素材的建议</button></div><small>没有合适素材的段落会保留口播。</small></div>
  </aside>`;
}
function previewLayer(c){if(!c)return '';
  const st=styleBy(c.style);if(!st)return '';
  if(st.id==='focus')return `<div class="preview-design focus-design"><span class="design-arc"></span><div class="design-kicker">THE FEEDBACK LOOP · 02</div><div class="design-center"><small>正反馈</small><strong>再改一版<br>就好了？</strong><em>“你会觉得再改一版也好”</em></div><div class="design-progress"><i></i><span>KEEP GOING / OR REST</span></div></div>`;
  if(st.id==='compare')return `<div class="preview-design compare-design"><div class="design-kicker">A MOMENT OF JUDGMENT</div><div class="compare-head">人，<br><b>做判断。</b></div><div class="compare-lines"><div><span>AI</span><strong>提出可能</strong></div><div><span>YOU</span><strong>决定方向</strong></div></div><div class="compare-index">02 / 03　·　AI 与人的协作</div></div>`;
  return `<div class="preview-design note-design"><div class="note-number">03 <span>/ ACTION</span></div><div class="note-paper"><span>写给明天的自己</span><strong>今天的事<br>先到这里。</strong><div class="note-rule"></div><p>设定一个收工时间<br>余下的，明天继续</p></div><span class="note-tail">TAKE A BREAK  ↗</span></div>`;
}
function stage(){const c=state.cards.find(x=>x.id===state.selected);return `<main class="stage"><div class="stage-head"><div><div class="eyebrow">PROJECT / 01</div><h1>把时间还给自己 <span>· 口播视频</span></h1></div><div class="stage-actions"><span class="draft-badge"><i></i>交互提案 · 本地演示</span><button class="button ghost" data-action="guide">操作说明</button><button class="button primary" data-action="review">查看审片清单　↗</button></div></div>
    <div class="stage-main"><div class="context-line"><span>画面预览</span><span class="dot-sep">/</span><b>竖屏 9:16</b><span class="context-right">当前片段 ${formatTime(c.start)}–${formatTime(c.end)}　<span class="preview-label">草稿模拟</span></span></div>
      <div class="preview-space"><div class="preview-surround"><div class="preview-frame"><video id="source-video" playsinline preload="metadata" src="${videoSource}" aria-label="原口播预览"></video><div class="grain"></div><div id="stage-overlay">${previewLayer(activeCard(state.cards,state.time))}</div><div id="subtitle" class="subtitle"></div></div><div class="frame-shadow"></div></div>
      <div class="stage-side-note"><span class="side-note-line"></span><span>DESIGNED FOR VERTICAL<br>CONTINUOUS STORYTELLING</span></div></div>
      <div class="player"><button class="round-control" data-action="step-back" title="后退 1 秒">↶</button><button class="play-control" data-action="play" aria-label="播放或暂停">${state.playing?icon.pause:icon.play}</button><button class="round-control" data-action="step-forward" title="前进 1 秒">↷</button><span class="player-time" id="player-time">${formatTime(state.time)}</span><span class="player-total">/ ${formatTime(DURATION)}</span><span class="player-spacer"></span><button class="sound-control" data-action="mute" title="静音切换">♫ 音频开</button><button class="ratio-control">9:16</button></div>
      <div class="transcript-strip"><div class="transcript-marker">此处口播</div><p>“${esc(c.text)}”</p><button data-action="show-reason">查看判断依据 ↗</button></div>
    </div></main>`;}
function inspector(){let c=state.cards.find(x=>x.id===state.selected),chosen=styleBy(c.style);return `<aside class="inspector panel"><div class="inspector-head"><div class="eyebrow">02 / THE DECISION</div><h2>这一段怎么处理<span>${String(state.cards.indexOf(c)+1).padStart(2,'0')} / 06</span></h2><div class="inspector-tabs"><button data-inspector="decision" class="${state.inspector==='decision'?'active':''}">判断依据</button><button data-inspector="edit" class="${state.inspector==='edit'?'active':''}">样式与动效</button></div></div>
    <div class="inspector-scroll">${c.timingChanged?'<div class="timing-warning">⚑ 时间已调整，请重新核对这一段与口播是否还匹配。</div>':''}${state.inspector==='decision'?`<div class="rationale"><span class="small-label">AGENT 的建议 <i class="tiny-mark ${c.decision}"></i></span><h3>${c.decision==='missing'?'先补素材，再决定':c.decision==='keep'?'这里保留口播':`此处使用「${esc(chosen?.name||'B-roll')}」`}</h3><p>${esc(c.reason)}</p><div class="reason-foot"><span>把握度：${esc(c.confidence)}</span><span>状态：${statusText(c)}</span></div></div><div class="evidence"><div class="section-heading">判断所用证据 <span>↗</span></div><div class="evidence-item"><span class="evidence-icon">⌁</span><div><strong>当前覆盖时段</strong><p>${formatTime(c.start)} — ${formatTime(c.end)} · 原建议：“${esc(c.text)}”</p></div></div><div class="evidence-item"><span class="evidence-icon">◇</span><div><strong>${c.decision==='missing'?'素材检索':'共享样式匹配'}</strong><p>${esc(c.evidence)}</p></div></div></div><div class="why-note"><span>✳</span><p>这是预设的交互样例，判断文案用于检验体验，不是此页面实时调用 AI 的结果。</p></div>`:`<div class="edit-section"><div class="section-heading">选择一种画面</div><button class="style-choice original ${c.decision==='keep'?'active':''}" data-decision="keep"><span class="original-icon">▣</span><span><strong>保留原口播</strong><small>这个位置不叠加 B-roll</small></span><span>↗</span></button>${STYLES.map(st=>`<button class="style-choice ${c.style===st.id&&c.decision==='broll'?'active':''}" data-style="${st.id}"><span class="style-swatch ${st.tone}">${st.motif}</span><span><strong>${st.name} <em>${st.version}</em></strong><small>${st.kind} · ${st.match}</small></span><span>↗</span></button>`).join('')}</div><div class="edit-section"><div class="section-heading">入场与画幅</div><label class="field-label">转场方式 <select data-effect="transition"><option ${c.transition==='直切'?'selected':''}>直切</option><option ${c.transition==='淡入淡出'?'selected':''}>淡入淡出</option><option ${c.transition==='推入'?'selected':''}>推入</option></select></label><label class="field-label">竖屏适配 <select data-effect="crop"><option ${c.crop==='竖屏重排'?'selected':''}>竖屏重排</option><option ${c.crop==='铺满'?'selected':''}>铺满</option><option ${c.crop==='保留完整构图'?'selected':''}>保留完整构图</option></select></label><p class="field-hint">时间线可拖动片段位置，拖左右边缘调整时长。</p></div>`}</div>
    <div class="inspector-footer"><button class="button ghost" data-action="keep-current">保留口播</button><button class="button primary" data-action="accept-current">${c.decision==='missing'?'用样式代替':c.status==='accepted'?'已采纳 ✓':'采纳这一段'}</button><small>修改只存在当前页面，刷新后恢复示例。</small></div></aside>`;}
function timeline(){let marks=[0,5,10,15,20,25,30,35,40,45,50],cards=state.cards.filter(c=>c.decision==='broll'||c.status==='missing');return `<section class="timeline"><div class="timeline-heading"><div><span class="eyebrow">03 / EDITING DESK</span><h2>时间线 <span>口播始终是底片 · B-roll 叠在上方</span></h2></div><div class="timeline-tools"><button data-action="undo" title="撤销" ${state.history.length?'':'disabled'}>${icon.back}</button><button data-action="redo" title="重做" ${state.future.length?'':'disabled'}>${icon.forward}</button><span class="tool-divider"></span><button data-action="zoom-out" title="缩小">−</button><span>${Math.round(state.zoom*100)}%</span><button data-action="zoom-in" title="放大">＋</button></div></div>
    <div class="timeline-body"><div class="track-labels"><div class="ruler-label">时间 / 秒</div><div class="track-label proposed"><b>01</b><span>画面覆盖<small>建议的 B-roll</small></span></div><div class="track-label caption"><b>02</b><span>字幕<small>跟随口播</small></span></div><div class="track-label source"><b>03</b><span>原始口播<small>画面 + 声音</small></span></div></div>
      <div class="timeline-scroll" id="timeline-scroll"><div class="timeline-content" id="timeline-content" style="width:${Math.round(state.zoom*100)}%;min-width:${Math.round(850*state.zoom)}px"><div class="ruler" data-ruler>${marks.map(n=>`<span class="ruler-tick" style="left:${n/DURATION*100}%">${String(n).padStart(2,'0')}s</span>`).join('')}</div>
       <div class="track overlay-track">${cards.map(c=>`<div class="timeline-clip ${c.status==='missing'?'missing':'suggested'} ${c.status==='accepted'?'accepted':''} ${state.selected===c.id?'selected':''}" data-clip="${c.id}" style="left:${c.start/DURATION*100}%;width:${(c.end-c.start)/DURATION*100}%"><span class="trim left" data-trim="left"></span><span class="clip-label">${c.status==='missing'?'＋ 待补画面':styleBy(c.style)?.name||'待选画面'}</span><span class="trim right" data-trim="right"></span></div>`).join('')}</div>
       <div class="track caption-track">${state.cards.map(c=>`<div class="caption-block" data-seek="${c.start}" style="left:${c.start/DURATION*100}%;width:${(c.end-c.start)/DURATION*100}%" title="${esc(c.text)}"><span>${esc(c.text)}</span></div>`).join('')}</div>
       <div class="track source-track"><div class="source-clip"><div class="waveform">${Array.from({length:160},(_,i)=>`<i style="height:${12+Math.round((.4+.6*Math.abs(Math.sin(i*.63)+Math.sin(i*.17))*.5)*29)}px"></i>`).join('')}</div><span>01-粗剪_无字幕.mov</span><span class="source-duration">53.0s</span></div></div><div class="playhead" id="playhead" style="left:${state.time/DURATION*100}%"><i></i></div></div></div></div>
    <div class="timeline-tip"><span>✳</span>点建议卡片可定位；在时间线上拖动片段、拉两端调整时长；按空格播放，⌘/Ctrl Z 撤销。<span class="tip-right">演示中的画面为前端模拟，不会改写原项目。</span></div></section>`;}
function altView(){if(state.view==='library')return `<div class="alt-view"><div class="alt-intro"><div class="eyebrow">SHARED LIBRARY / 共享资产</div><h1>一次复刻，反复使用。</h1><p>复刻成果属于独立资产库。这里演示从共享库挑选样式，再带回项目制作；卡片是界面样例。</p><button class="button primary" data-view="make">返回项目制作 ↗</button></div><div class="library-grid">${STYLES.map(st=>`<article class="library-card"><div class="library-art ${st.tone}"><span>${st.motif}</span><small>${st.kind.toUpperCase()}</small></div><div class="library-meta"><span>演示样式 · ${st.version}</span><h2>${st.name}</h2><p>${st.match}</p><button data-view="make" data-library-style="${st.id}">放到当前片段 ↗</button></div></article>`).join('')}</div><div class="library-footer">研究记录 → 复刻项目 → 验收版本 → 共享样式 → 不同项目的制作片段</div></div>`;
  return `<div class="alt-view"><div class="alt-intro"><div class="eyebrow">REFERENCE STUDY / 参考研究</div><h1>看见一个好镜头，先把它读懂。</h1><p>截取参考片里的片段，记下叙事用途、元素和运动，再决定是否复刻。这里展示研究到制作的操作路径，不产生实际复刻任务。</p><button class="button primary" data-view="make">进入项目制作 ↗</button></div><div class="research-flow"><article><span>01 / 研究</span><h2>选中参考片段</h2><p>观察镜头目的、文字节奏、画面比例和可替换元素。</p></article><div class="flow-arrow">→</div><article><span>02 / 复刻</span><h2>得到可替换样式</h2><p>逐场景核对画面与动作，保留来源和验收版本。</p></article><div class="flow-arrow">→</div><article><span>03 / 使用</span><h2>Agent 匹配到口播</h2><p>说清为什么合适；你能改、能拒绝、能批量审看。</p></article></div><div class="research-note">当前 Demo 聚焦第三步：先检验“判断 → 修改 → 时间线审片”是否顺手。</div></div>`;}
function render(){let time=state.time,playing=state.playing;
  root.innerHTML=`<div class="app-shell"><header class="topbar"><button class="brand" data-view="make"><span class="brand-symbol">✳</span><span>AI <b>工作台</b></span></button><span class="top-divider"></span><div class="project-breadcrumb">制作项目 <span>／</span> 把时间还给自己 <span class="project-arrow">⌄</span></div><nav class="top-nav"><button data-view="research" class="${state.view==='research'?'active':''}">参考研究</button><button data-view="library" class="${state.view==='library'?'active':''}">共享样式</button><button data-view="make" class="${state.view==='make'?'active':''}">项目制作</button></nav><div class="top-right"><span class="autosave">● 页面内演示</span><button class="avatar" title="本地演示">L</button></div></header>${state.view==='make'?`<div class="work-area">${decisionPanel()}${stage()}${inspector()}</div>${timeline()}`:altView()}<div class="notice ${state.notice?'show':''}" role="status">${esc(state.notice)}</div><div class="modal-backdrop" id="modal" hidden><div class="modal"><button class="modal-close" data-action="close-modal">×</button><div id="modal-body"></div></div></div></div>`;
  let video=document.querySelector('#source-video');if(video){video.addEventListener('loadedmetadata',()=>{video.currentTime=time;updateLive();if(playing)video.play().catch(()=>{state={...state,playing:false};});},{once:true});if(video.readyState>=1)video.currentTime=time;video.muted=false;video.addEventListener('timeupdate',()=>{if(video.readyState<1)return;state={...state,time:video.currentTime};updateLive();});video.addEventListener('ended',()=>{state={...state,playing:false};render();});updateLive();}
}
function updateLive(){const playhead=document.querySelector('#playhead'),clock=document.querySelector('#player-time');if(playhead)playhead.style.left=`${state.time/DURATION*100}%`;if(clock)clock.textContent=formatTime(state.time);const layer=document.querySelector('#stage-overlay');if(layer){const active=activeCard(state.cards,state.time);if(layer.dataset.card!==(active?.id||'')){layer.dataset.card=active?.id||'';layer.innerHTML=previewLayer(active);}let progress=active?Math.min(1,(state.time-active.start)/.45,(active.end-state.time)/.45):1;layer.style.opacity=active&&active.transition!=='直切'?Math.max(0,progress):1;layer.style.transform=active?.transition==='推入'?`translateX(${Math.min(0,(state.time-active.start)/.45-1)*25}%)`:'';layer.classList.toggle('keep-aspect',active?.crop==='保留完整构图');layer.classList.toggle('cover',active?.crop==='铺满');const caption=document.querySelector('#subtitle');let card=state.cards.find(c=>state.time>=c.start&&state.time<c.end);if(caption)caption.textContent=card?.text||'';}}
function dispatch(a){state=action(state,a);render();}
function toast(message){state={...state,notice:message};let el=document.querySelector('.notice');if(el){el.textContent=message;el.classList.add('show');}clearTimeout(toast.timer);toast.timer=setTimeout(()=>{state={...state,notice:''};el?.classList.remove('show');},3500);}
function modal(title,body){const el=document.querySelector('#modal');el.hidden=false;document.querySelector('#modal-body').innerHTML=`<div class="eyebrow">INTERACTION PROPOSAL</div><h2>${title}</h2>${body}`;}
root.addEventListener('click',e=>{const t=e.target.closest('button,[data-select],[data-seek]');if(!t)return;
 if(t.dataset.view){dispatch({type:'view',value:t.dataset.view});if(t.dataset.libraryStyle){dispatch({type:'setStyle',id:state.selected,style:t.dataset.libraryStyle});toast('已放入当前片段的演示草稿，请在项目制作中审看。');}return;}
 if(t.dataset.filter){dispatch({type:'filter',value:t.dataset.filter});return;}
 if(t.dataset.inspector){dispatch({type:'inspector',value:t.dataset.inspector});return;}
 if(t.dataset.style){dispatch({type:'setStyle',id:state.selected,style:t.dataset.style});toast('样式已替换；请在预览和时间线上检查。');return;}
 if(t.dataset.decision){dispatch({type:'setDecision',id:state.selected,decision:t.dataset.decision});return;}
 if(t.dataset.seek){dispatch({type:'seek',time:+t.dataset.seek});return;}
 if(t.dataset.select&&!e.target.closest('label,input')){dispatch({type:'select',id:t.dataset.select});return;}
 if(!t.dataset.action)return;
 let c=state.cards.find(x=>x.id===state.selected);
 switch(t.dataset.action){
 case 'play':state={...state,playing:!state.playing};document.querySelector('#source-video')?.[state.playing?'play':'pause']();t.textContent=state.playing?icon.pause:icon.play;break;
 case 'step-back':dispatch({type:'seek',time:state.time-1});break;
 case 'step-forward':dispatch({type:'seek',time:state.time+1});break;
 case 'mute':{let v=document.querySelector('#source-video');v.muted=!v.muted;t.textContent=v.muted?'♫ 已静音':'♫ 音频开';break;}
 case 'show-reason':dispatch({type:'inspector',value:'decision'});break;
 case 'keep-current':dispatch({type:'setDecision',id:c.id,decision:'keep'});break;
 case 'accept-current':if(!c.style){dispatch({type:'inspector',value:'edit'});toast('这里还没有素材；可以选用共享样式，或保留口播。');}else{dispatch({type:'setDecision',id:c.id,decision:'broll'});}break;
 case 'bulk-keep':dispatch({type:'bulk',decision:'keep'});break;
 case 'bulk-accept':dispatch({type:'bulk',decision:'accept'});break;
 case 'clear-check':state={...state,checked:[]};render();break;
 case 'undo':dispatch({type:'undo'});break;
 case 'redo':dispatch({type:'redo'});break;
 case 'zoom-in':dispatch({type:'zoom',delta:.25});break;
 case 'zoom-out':dispatch({type:'zoom',delta:-.25});break;
 case 'close-modal':document.querySelector('#modal').hidden=true;break;
 case 'guide':modal('怎么体验这版工作台',`<p>先在左侧看 Agent 的建议和「不加 B-roll」的判断；点一段，预览和时间线一起定位。右侧可以查看证据、换样式、改转场。最后勾选几段批量取舍，再拖动下方 B-roll 片段的主体或两端。</p><p>预览播放的是项目里的真实口播代理文件；叠加样式、动效与审片结论是前端模拟。此页没有后端、没有真实保存或渲染。</p><button class="button primary" data-action="close-modal">开始体验 ↗</button>`);break;
 case 'review':{let pending=state.cards.filter(x=>x.status==='pending').length,missing=state.cards.filter(x=>x.status==='missing').length;modal('审片清单',`<div class="review-stats"><div><strong>${pending}</strong><span>待判断</span></div><div><strong>${missing}</strong><span>素材缺口</span></div><div><strong>${state.cards.length-pending-missing}</strong><span>已处理</span></div></div><p>建议先处理素材缺口，再播放全片检查节奏。这个演示只验证工作流和前端反馈；此处不会确认真实项目，也不会导出文件。</p><div class="modal-actions"><button class="button ghost" data-action="close-modal">继续审看</button><button class="button primary" data-action="demo-export">我了解这版流程 ↗</button></div>`);break;}
 case 'demo-export':document.querySelector('#modal').hidden=true;toast('收到：这里是前端操作提案。真正保存与渲染要等你认可交互后再接入。');break;
 }
});
root.addEventListener('change',e=>{let t=e.target;if(t.dataset.check){state=action(state,{type:'toggleCheck',id:t.dataset.check});render();}if(t.hasAttribute('data-check-all')){state=action(state,{type:'checkVisible',ids:displayCards().map(c=>c.id),checked:t.checked});render();}if(t.dataset.effect){dispatch({type:'setEffect',id:state.selected,field:t.dataset.effect,value:t.value});}});
root.addEventListener('keydown',e=>{if(e.target.matches('[data-select]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();dispatch({type:'select',id:e.target.dataset.select});}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(e.code==='Space'){e.preventDefault();document.querySelector('.play-control')?.click();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();dispatch({type:e.shiftKey?'redo':'undo'});}});
let drag=null;
root.addEventListener('pointerdown',e=>{if(state.view!=='make')return;let clip=e.target.closest('.timeline-clip'),ruler=e.target.closest('[data-ruler]');if(clip){let rect=clip.parentElement.getBoundingClientRect();drag={id:clip.dataset.clip,edge:e.target.closest('[data-trim]')?.dataset.trim||null,startX:e.clientX,width:rect.width,original:state.cards.find(c=>c.id===clip.dataset.clip).start,el:clip,moved:false};e.preventDefault();return;}if(ruler){let rect=ruler.getBoundingClientRect();dispatch({type:'seek',time:(e.clientX-rect.left)/rect.width*DURATION});}});
document.addEventListener('pointermove',e=>{if(!drag)return;let delta=(e.clientX-drag.startX)/drag.width*DURATION;if(Math.abs(e.clientX-drag.startX)>3)drag.moved=true;let c=state.cards.find(x=>x.id===drag.id),target=drag.edge==='left'?c.start+delta:drag.edge==='right'?c.end+delta:c.start+delta;drag.target=target;let edge=drag.el;if(drag.edge==='left'){edge.style.left=`${clamp(target,0,c.end-.6)/DURATION*100}%`;edge.style.width=`${(c.end-clamp(target,0,c.end-.6))/DURATION*100}%`;}else if(drag.edge==='right'){edge.style.width=`${(clamp(target,c.start+.6,DURATION)-c.start)/DURATION*100}%`;}else edge.style.left=`${clamp(target,0,DURATION-(c.end-c.start))/DURATION*100}%`;});
document.addEventListener('pointerup',()=>{if(!drag)return;let d=drag;drag=null;if(!d.moved){dispatch({type:'select',id:d.id});return;}dispatch(d.edge?{type:'trim',id:d.id,edge:d.edge,time:d.target}:{type:'move',id:d.id,start:d.target});});
render();
